package net.civeira.phylax.feature.observe.observeddashboard.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.observe.observeddashboard.domain.ObservedDashboard;
import net.civeira.phylax.feature.observe.observeddashboard.domain.event.ObservedDashboardEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class ObservedDashboardEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<ObservedDashboardEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final ObservedDashboard entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
